// ui.tsx holds the presentational primitives every screen shares, in
// shadcn's own shape: a `cn()`-merged className, class-variance-authority for
// variants, plain semantic HTML underneath.
//
// Written here rather than generated by the shadcn CLI, and without Radix,
// because every component this application actually needs — a button, a
// table, a badge, a card — is a native element with no interaction state to
// manage. Radix earns its place on a dialog, a combobox, or a menu, none of
// which six read-only tables and one button require. If a later screen needs
// one, `npx shadcn add dialog` drops it in beside these and this file's
// conventions already match what it generates.

import { cva, type VariantProps } from 'class-variance-authority'
import type { ButtonHTMLAttributes, HTMLAttributes, ReactNode, TdHTMLAttributes } from 'react'

import { cn } from './lib'

const buttonVariants = cva(
  'inline-flex items-center justify-center gap-2 rounded-md text-sm font-medium ' +
    'transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 ' +
    'focus-visible:outline-primary disabled:pointer-events-none disabled:opacity-50',
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:opacity-90',
        destructive: 'bg-destructive text-destructive-foreground hover:opacity-90',
        outline: 'border border-border bg-background hover:bg-accent',
        ghost: 'hover:bg-accent',
      },
      size: {
        default: 'h-9 px-4 py-2',
        sm: 'h-8 rounded-md px-3 text-xs',
      },
    },
    defaultVariants: { variant: 'default', size: 'default' },
  },
)

export type ButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & VariantProps<typeof buttonVariants>

export function Button({ className, variant, size, ...props }: ButtonProps) {
  return <button className={cn(buttonVariants({ variant, size }), className)} {...props} />
}

const badgeVariants = cva(
  'inline-flex items-center rounded-full border px-2 py-0.5 text-xs font-medium whitespace-nowrap',
  {
    variants: {
      tone: {
        neutral: 'border-border bg-muted text-muted-foreground',
        good: 'border-transparent bg-primary text-primary-foreground',
        warn: 'border-destructive/40 text-destructive',
      },
    },
    defaultVariants: { tone: 'neutral' },
  },
)

export type BadgeProps = HTMLAttributes<HTMLSpanElement> & VariantProps<typeof badgeVariants>

export function Badge({ className, tone, ...props }: BadgeProps) {
  return <span className={cn(badgeVariants({ tone }), className)} {...props} />
}

export function Card({ className, ...props }: HTMLAttributes<HTMLDivElement>) {
  return <div className={cn('rounded-lg border border-border bg-background', className)} {...props} />
}

/** A screen's heading and its explanatory line. The line is not decoration:
 *  several of these tables show a value whose meaning is not obvious from its
 *  column name, and the alternative to saying so is an operator guessing. */
export function ScreenHeader({ title, children }: { title: string; children?: ReactNode }) {
  return (
    <header className="mb-4">
      <h2 className="text-lg font-semibold">{title}</h2>
      {children ? <p className="mt-1 max-w-3xl text-sm text-muted-foreground">{children}</p> : null}
    </header>
  )
}

/** A horizontally scrollable table wrapper. Several of these tables are wider
 *  than a laptop; the scroll belongs to the table, never to the page body. */
export function Table({ children }: { children: ReactNode }) {
  return (
    <div className="w-full overflow-x-auto rounded-lg border border-border">
      <table className="w-full caption-bottom text-sm">{children}</table>
    </div>
  )
}

export function THead({ columns }: { columns: string[] }) {
  return (
    <thead className="bg-muted">
      <tr>
        {columns.map((c) => (
          <th key={c} scope="col" className="px-3 py-2 text-left font-medium text-muted-foreground">
            {c}
          </th>
        ))}
      </tr>
    </thead>
  )
}

export function TRow({ children }: { children: ReactNode }) {
  return <tr className="border-t border-border align-top">{children}</tr>
}

export function TCell({ className, ...props }: TdHTMLAttributes<HTMLTableCellElement>) {
  return <td className={cn('px-3 py-2', className)} {...props} />
}

/** The one place an empty list is rendered, so "this tenant has none" always
 *  reads the same and is never mistaken for "still loading" or "failed". */
export function EmptyRow({ colSpan, children }: { colSpan: number; children: ReactNode }) {
  return (
    <TRow>
      <TCell colSpan={colSpan} className="py-6 text-center text-muted-foreground">
        {children}
      </TCell>
    </TRow>
  )
}

/** An error banner. Always shows the server's own words: a 403 from the PAP
 *  says which role floor refused the request, and paraphrasing it would lose
 *  the one detail the operator needs (N14 — the server decides, this screen
 *  reports). */
export function ErrorBanner({ children }: { children: ReactNode }) {
  return (
    <div
      role="alert"
      className="mb-4 rounded-md border border-destructive/40 bg-destructive/10 px-3 py-2 text-sm text-destructive"
    >
      {children}
    </div>
  )
}
